/* hippsim service worker (generated by tools/build_app.py; do not edit app/sw.js by hand).
   Precaches the app shell, every simulator page and every engine file, so the app works offline.
   A new build changes VERSION: the new worker installs the new files, then removes the old cache. */
const VERSION = '7c92f68221';
const CACHE = 'hippsim-' + VERSION;
const SHELL = [
"about.html",
"atlas.html",
"atlasdata.js",
"bapdata.js",
"ccfdata.js",
"docs.html",
"file.html",
"gfdata.js",
"hs-app-config.js",
"hs-app.js",
"hs-backend-firebase.js",
"hs-cable.js",
"hs-cards.js",
"hs-core.js",
"hs-file.js",
"hs-help.js",
"hs-layout.js",
"hs-models.js",
"hs-morph-extra.js",
"hs-ngc.js",
"hs-page.js",
"hs-questions.js",
"hs-registry.js",
"hs-run.js",
"hs-sim.css",
"icons/apple-touch-icon.png",
"icons/favicon-64.png",
"icons/icon-192.png",
"icons/icon-512.png",
"icons/maskable-512.png",
"index.html",
"library.html",
"manifest.webmanifest",
"modellab.js",
"models.html",
"morph.js",
"morph2.js",
"neuronviewer.css",
"neuronviewer.js",
"ngstudio.js",
"realbio.js",
"router.js",
"runs.html",
"sim-ca1-neuron.html",
"sim-circuit.html",
"sim-lab-models.html",
"sim-other-systems.html",
"sim-studio.html",
"simulator.html",
"styles.css",
"validation.html",
"vendor/mathjax/tex-svg.js",
"verify.js",
"wb-core.js"
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('hippsim-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin) return;
  // pages: offline-capable, ignoring the #tool part of the address
  if (req.mode === 'navigate') {
    e.respondWith(caches.match(url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname, {ignoreSearch: true})
      .then(hit => hit || fetch(req).catch(() => caches.match('index.html'))));
    return;
  }
  // everything else: cache first; files not in the shell (SWC, code, data) are cached the first time they are opened
  e.respondWith(caches.match(req, {ignoreSearch: true}).then(hit => hit || fetch(req).then(res => {
    if (res.ok && res.type === 'basic') { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  })));
});
